function ReadFunctions($lines) {
 $functions=[System.Collections.Generic.List[object]]::new();$current=$null
 foreach($line in $lines) {
  if($line -match '^([0-9a-f]{16}) <(.+)>:$') {
   $start=[Convert]::ToInt64($Matches[1],16);$name=$Matches[2]
   $role=if($name.Contains('HandwrittenDefaultPairs')) {'Hand'} else {'Required'}
   $current=[pscustomobject]@{Role=$role;Start=$start;Code=[System.Collections.Generic.List[object]]::new()};$functions.Add($current)
  } elseif($null -ne $current -and $line -match '^\s+([0-9a-f]{1,8}):\s+(\S.*)$') {$current.Code.Add([pscustomobject]@{Address=[Convert]::ToInt64($Matches[1],16);Text=$Matches[2]})}
 }
 foreach($f in $functions) {while($f.Code.Count -gt 0 -and $f.Code[$f.Code.Count-1].Text -match '^nop') {$f.Code.RemoveAt($f.Code.Count-1)}}
 return $functions
}
$sets=@([pscustomobject]@{Version='3b';Functions=@(ReadFunctions $oldDump)},[pscustomobject]@{Version='fc44';Functions=@(ReadFunctions $newDump)})
foreach($set in $sets) {
 foreach($f in $set.Functions) {
  $end=$f.Code[$f.Code.Count-1].Address+1
  $pushes=0;$allocation=0
