  $head=@($f.Code | Select-Object -First 40)
  $directClears=@($head | Where-Object {$_.Text -match '^mov[a-z]+\s+%xmm4, (?:0x[0-9a-f]+)?\(%rsp\)'}).Count
  $indexedClears=@($head | Where-Object {$_.Text -match '^mov[a-z]+\s+%xmm4, .*\(%rsp,%rax\)'}).Count
  $initial=0;$step=0
  foreach($row in $head) {
   if($row.Text -match '^movabsq\s+\$-0x([0-9a-f]+), %rax') {$initial=[Convert]::ToInt64($Matches[1],16)}
   if($row.Text -match '^addq\s+\$0x([0-9a-f]+), %rax') {$step=[Convert]::ToInt64($Matches[1],16)}
  }
  $initBytes=$directClears*16
  if($initial -gt 0 -and $step -gt 0) {$initBytes+=($initial/$step)*$indexedClears*16}
  [pscustomobject]@{Version=$set.Version;Role=$f.Role;Start=('0x{0:x}' -f $f.Start);EndExclusive=('0x{0:x}' -f $end);Bytes=$end-$f.Start;Instructions=$f.Code.Count;StackBytes=$pushes*8+$allocation;InitialXmm4Bytes=$initBytes;DirectXmm4Clears=$directClears;LoopInitial=$initial;LoopStep=$step;IndexedClears=$indexedClears;CopyCallSites=$copies.Count;CallSites=@($f.Code | Where-Object {$_.Text -match '^callq'}).Count;StartMod32=$f.Start%32;StartMod64=$f.Start%64} | ConvertTo-Json -Compress
  foreach($row in $f.Code | Select-Object -First 38) {('ENTRY '+$set.Version+' '+$f.Role+' 0x{0:x} ' -f $row.Address)+($row.Text -replace '<[^\r\n]*>','<symbol>')}
  for($i=0;$i -lt $f.Code.Count;$i++) {
   $row=$f.Code[$i]
   if($row.Text.Contains('BulkMoveWithWriteBarrier') -or $row.Text.Contains('Buffer__Memmove')) {
    'COPY CONTEXT '+$set.Version+' '+$f.Role
    $begin=[Math]::Max(0,$i-5)
    foreach($context in $f.Code[$begin..$i]) {('0x{0:x} ' -f $context.Address)+($context.Text -replace '<[^\r\n]*>','<symbol>')}
   }
   if($row.Text -match '^callq' -and ($row.Text.Contains('QueryRow') -or $row.Text.Contains('QueryChunk') -or $row.Text.Contains('BindColumns'))) {('ITERATOR CALL '+$set.Version+' '+$f.Role+' 0x{0:x} ' -f $row.Address)+$row.Text}
   if($row.Text -match '^(j\w+)\s+0x([0-9a-f]+)') {
    $mnemonic=$Matches[1];$target=[Convert]::ToInt64($Matches[2],16)
    if($target -lt $row.Address) {('BACKEDGE '+$set.Version+' '+$f.Role+' 0x{0:x} -> 0x{1:x} startMod32={2} startMod64={3} targetMod32={4} targetMod64={5}' -f $row.Address,$target,($row.Address%32),($row.Address%64),($target%32),($target%64))}
   }
  }
 }
